import unittest

class MedianStreamTests(unittest.TestCase):
    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            MedianStream().median()

    def test_odd_count(self):
        values = MedianStream()
        for value in (8, 1, 5):
            values.add(value)
        self.assertEqual(values.median(), 5)

    def test_even_count(self):
        values = MedianStream()
        for value in (8, 1, 5, 2):
            values.add(value)
        self.assertEqual(values.median(), 3.5)

    def test_duplicates_and_negatives(self):
        values = MedianStream()
        for value in (-4, -4, 10, 10, 2):
            values.add(value)
        self.assertEqual(values.median(), 2)

    def test_order_independent(self):
        values = MedianStream()
        for value in (20, -1, 4, 8):
            values.add(value)
        self.assertEqual(values.median(), 6)

if __name__ == '__main__':
    unittest.main(verbosity=2)
